"""Embed AMD FidelityFX Super Resolution 2.2.1 (MIT) shaders for the D3D11 port.

Reads the unmodified upstream files in ThirdParty/fsr2/shaders and writes
Source/fsr2_embedded.h: one HLSL source holding every pass the renderer runs,
selected by FSR2_PASS at compile time (Source/fsr2_upscaler.h). Each pass file
is split at its two shared includes (callbacks, common): its binding defines
go before the shared part, the rest after it. #include lines are expanded in
place; comments and blank lines are dropped to keep the DLL small. A missing
include (only inside the FP16 branch, which is never compiled) stays as is.
"""
import re
from pathlib import Path

root = Path(__file__).resolve().parents[1]
shaders = root / 'ThirdParty/fsr2/shaders'
# FSR2_PASS index -> upstream pass file (order matches Fsr2Pass in fsr2_upscaler.h).
passes = ['compute_luminance_pyramid', 'reconstruct_previous_depth', 'depth_clip', 'lock', 'accumulate', 'rcas']
shared = ['ffx_fsr2_callbacks_hlsl.h', 'ffx_fsr2_common.h']


def strip(text):
    text = text.replace('\r\n', '\n').replace('\\\n', '\x01')  # keep macro continuations intact
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.S)
    text = re.sub(r'//[^\n\x01]*', '', text)
    lines = [line.rstrip() for line in text.split('\n')]
    return '\n'.join(line for line in lines if line.strip()).replace('\x01', '\\\n')


def expand(text):
    def include(match):
        path = shaders / match.group(1)
        return expand(strip(path.read_text(encoding='latin-1'))) if path.exists() else match.group(0)
    return re.sub(r'^[ \t]*#[ \t]*include[ \t]+"([^"]+)"', include, text, flags=re.M)


heads, tails = [], []
for index, name in enumerate(passes):
    text = strip((shaders / f'ffx_fsr2_{name}_pass.hlsl').read_text(encoding='latin-1'))
    marks = [re.search(r'^#include "%s"\n' % re.escape(h), text, flags=re.M) for h in shared]
    if not all(marks) or marks[0].end() != marks[1].start():
        raise SystemExit(f'{name}: the pass no longer starts with the shared includes')
    heads.append(text[:marks[0].start()])
    tails.append(expand(text[marks[1].end():]))

license_text = (root / 'ThirdParty/fsr2/LICENSE.txt').read_text(encoding='latin-1').replace('\r\n', '\n').strip()
source = '/*\n' + license_text + '\n*/\n'
for index, head in enumerate(heads):
    source += ('#if' if index == 0 else '#elif') + f' FSR2_PASS == {index}\n' + head + '\n'
source += '#endif\n' + expand('\n'.join(f'#include "{h}"' for h in shared)) + '\n'
for index, tail in enumerate(tails):
    source += ('#if' if index == 0 else '#elif') + f' FSR2_PASS == {index}\n' + tail + '\n'
source += '#endif\n'
if ')FSR2"' in source:
    raise SystemExit('raw string delimiter inside the source')

parts = [source[i:i + 8000] for i in range(0, len(source), 8000)]
output = '// Generated by Tools/embed-fsr2.py. Do not edit.\n'
output += '// AMD FidelityFX Super Resolution 2.2.1; MIT licence: ThirdParty/fsr2/LICENSE.txt\n'
output += '#pragma once\n#include <string>\nnamespace owned {\ninline std::string fsr2_shader_library() {\n std::string result;\n'
output += f' result.reserve({len(source)});\n'
for part in parts:
    output += ' result += R"FSR2(' + part + ')FSR2";\n'
output += ' return result;\n}\n}\n'
(root / 'Source/fsr2_embedded.h').write_text(output, encoding='utf-8', newline='\n')
print(f'fsr2_embedded.h: {len(source)} characters')
